// GeneratedAPIIDs returns sorted TR codes for generated stock/ETF/US APIs.
func GeneratedAPIIDs() []string {
	ids := make([]string, 0, len(GeneratedAPIRegistry))
	for id := range GeneratedAPIRegistry {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}
